def mean_absolute_deviation(numbers: list[float]) -> float:
    """Calculate the mean absolute deviation (MAD) around the mean."""
    if numbers is None:
        raise ValueError("Input cannot be None")
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("Input must be a list or tuple of numbers")
    if len(numbers) == 0:
        raise ValueError("Input list must contain at least one number")
    # Verify all elements are numeric
    for idx, x in enumerate(numbers):
        if not isinstance(x, (int, float)):
            raise TypeError(f"Element at index {idx} is not a number: {x!r}")
    n = len(numbers)
    mean = sum(numbers) / n
    mad = sum(abs(x - mean) for x in numbers) / n
    return mad

def find_topmost_carpet(n, carpets, point) -> int:
    """
    Find the topmost carpet covering a given point on the coordinate plane.

    Args:
        n (int): The total number of carpets.
        carpets (list of tuples): Each tuple contains four integers (a, b, g, k)
            where (a, b) is the bottom-left corner of the carpet and (g, k) are
            the lengths along the x and y axes, respectively.
        point (tuple): A tuple (x, y) with the coordinates of the point to check.

    Returns:
        int: 1-based index of the topmost carpet covering the point, or -1 if none.
    """
    try:
        # Basic input validation
        if not isinstance(n, int) or n < 0:
            return -1
        if not isinstance(carpets, list) or len(carpets) != n:
            return -1
        if not isinstance(point, tuple) or len(point) != 2:
            return -1
        x, y = point
        if not (isinstance(x, int) and isinstance(y, int)):
            return -1

        topmost = -1
        for idx, c in enumerate(carpets, start=1):
            if not isinstance(c, tuple) or len(c) != 4:
                return -1
            a, b, g, k = c
            if not all(isinstance(v, int) for v in (a, b, g, k)):
                return -1
            if g < 0 or k < 0:
                return -1
            if a <= x <= a + g and b <= y <= b + k:
                topmost = idx
        return topmost
    except Exception:
        # Any unexpected runtime issue results in -1
        return -1

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each value can be collected at most once, even if both paths pass through it.
    The function assumes moves are only right or down from the top-left corner
    (1,1) to the bottom-right corner (N,N). The grid is initially empty and
    values are provided via grid_values, which is terminated by a tuple (0,0,0).
    """
    try:
        if N <= 0:
            return 0
        # Build the grid
        grid = [[0] * N for _ in range(N)]
        for entry in grid_values:
            if not isinstance(entry, (list, tuple)) or len(entry) != 3:
                continue
            x, y, val = entry
            if x == 0 and y == 0 and val == 0:
                break
            if 1 <= x <= N and 1 <= y <= N:
                grid[x - 1][y - 1] = val

        # Dynamic programming for two walkers
        NEG_INF = -10 ** 18
        dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        dp[1][1] = grid[0][0]  # both start at (1,1)

        for step in range(2, 2 * N + 1):
            new_dp = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
            max_coord = min(N, step)
            for x1 in range(1, max_coord + 1):
                y1 = step - x1
                if y1 < 1 or y1 > N:
                    continue
                for x2 in range(1, max_coord + 1):
                    y2 = step - x2
                    if y2 < 1 or y2 > N:
                        continue
                    best = NEG_INF
                    # possible previous moves (stay or -1)
                    for dx1, dx2 in [(0, 0), (-1, 0), (0, -1), (-1, -1)]:
                        prev_x1 = x1 + dx1
                        prev_x2 = x2 + dx2
                        if prev_x1 < 1 or prev_x2 < 1:
                            continue
                        val = dp[prev_x1][prev_x2]
                        if val > best:
                            best = val
                    if best == NEG_INF:
                        continue
                    cell_sum = grid[x1 - 1][y1 - 1]
                    if x1 != x2 or y1 != y2:
                        cell_sum += grid[x2 - 1][y2 - 1]
                    new_dp[x1][x2] = best + cell_sum
            dp = new_dp

        return dp[N][N]
    except Exception:
        return 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    Args:
    - N (int): The size of the grid (N x N).
    - grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
      the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
      The list is terminated by a tuple with all zeros.

    Returns:
    - int: The maximum sum of values collected on the two paths.
    """
    from math import inf
    if N <= 0:
        return 0

    # Initialize grid with zeros (1-based indexing)
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # dp[i1][i2] = maximum collected value when path1 at (i1, j1) and path2 at (i2, j2)
    dp_prev = [[-inf] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps k = 3 to 2N (since starting at (1,1) counts as step 2)
    for k in range(3, 2 * N + 1):
        dp_cur = [[-inf] * (N + 1) for _ in range(N + 1)]
        for i1 in range(1, N + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, N + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                # Compute best previous position
                best_prev = -inf
                for di1 in (0, 1):  # came from left (i1-1) or from up (i1)
                    pi1 = i1 - di1
                    if pi1 < 1 or pi1 > N:
                        continue
                    for di2 in (0, 1):
                        pi2 = i2 - di2
                        if pi2 < 1 or pi2 > N:
                            continue
                        if pi1 == i1 and pi2 == i2:
                            continue  # must come from a previous step
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > best_prev:
                            best_prev = prev_val
                if best_prev == -inf:
                    continue
                # Add current cell values, ensuring no double count
                add_val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add_val += grid[i2][j2]
                dp_cur[i1][i2] = best_prev + add_val
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != -inf else 0

def find_number_combinations():
    """
    Generate all unique combinations of three numbers, each formed from the digits 1 to 9 without repetition,
    such that the second number is twice the first and the third is three times the first.

    Returns:
        list of tuples: A sorted list of tuples, where each tuple contains three integers representing the
                        valid number combinations in ascending order based on the first number.
    """
    # Helper function to validate a number: only digits 1-9, no repeats within the number.
    def _is_valid(n):
