        if '0' in s:
            return False
        return len(set(s)) == len(s)

    numbers = []

    # Recursively generate all numbers with 1 to 6 unique digits from 1-9
    def _backtrack(current, used, depth):
        if depth > 0:
            numbers.append(current)
        if depth == 6:
            return
        for d in range(1, 10):  # digits 1-9
            if d not in used:
                _backtrack(current * 10 + d, used | {d}, depth + 1)

    try:
        _backtrack(0, set(), 0)
        results = []
        for x in numbers:
            y = 2 * x
            z = 3 * x
            if _is_valid(y) and _is_valid(z):
                results.append((x, y, z))
        results.sort(key=lambda t: t[0])
        return results
    except Exception:
        # In case of any unexpected errors, return an empty list
        return []

