        min_row, max_row = min(x, p), max(x, p)
        min_col, max_col = min(y, q), max(y, q)
        # horizontal aisle between rows r and r+1 separates if min_row <= r < max_row
        for r in range(min_row, max_row):
            if 1 <= r < M:
                horizontal_counts[r] += 1
        # vertical aisle between columns c and c+1 separates if min_col <= c < max_col
        for c in range(min_col, max_col):
            if 1 <= c < N:
                vertical_counts[c] += 1

    # Select top K horizontal aisles
    rows_candidates = [(cnt, idx) for idx, cnt in enumerate(horizontal_counts) if 1 <= idx < M]
    rows_candidates.sort(key=lambda x: (-x[0], x[1]))
    selected_rows = [idx for _, idx in rows_candidates[:K]]
    selected_rows.sort()

    # Select top L vertical aisles
    cols_candidates = [(cnt, idx) for idx, cnt in enumerate(vertical_counts) if 1 <= idx < N]
