    selected_cols = [idx for _, idx in cols_candidates[:L]]
    selected_cols.sort()

    # Convert to space-separated strings
    rows_str = " ".join(str(r) for r in selected_rows) if selected_rows else ""
    cols_str = " ".join(str(c) for c in selected_cols) if selected_cols else ""

    return (rows_str, cols_str)

