            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def decode(encoded: str, original: str, message: str) -> str:
    """Decode a message using a substitution mapping derived from an encoded–original pair.

    The mapping is built from corresponding characters of ``encoded`` and ``original``.
    If a character in ``encoded`` maps to two different characters in ``original`` a
    contradiction is found and the function returns ``"Failed"``.  The mapping must
    contain all 26 uppercase letters.  The message is decoded by replacing each
    character using this mapping.  If the message contains a character that is not
    present in the mapping the function likewise returns ``"Failed"``.

    Parameters
    ----------
    encoded : str
        The encoded representation of text.
    original : str
        The original (plain) representation corresponding to ``encoded``.
    message : str
        The encrypted message to decode.

    Returns
    -------
    str
        The decoded message or ``"Failed"`` if decoding is impossible.
    """
    try:
        if not isinstance(encoded, str) or not isinstance(original, str) or not isinstance(message, str):
            return "Failed"
        if len(encoded) != len(original):
            return "Failed"

        mapping: dict[str, str] = {}
        for enc_char, orig_char in zip(encoded, original):
            if enc_char in mapping:
                if mapping[enc_char] != orig_char:
                    return "Failed"
            else:
                mapping[enc_char] = orig_char

        if len(mapping) < 26:
            return "Failed"

        decoded = []
        for ch in message:
            if ch not in mapping:
                return "Failed"
            decoded.append(mapping[ch])
        return "".join(decoded)
    except Exception:
        return "Failed"

def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer n into k parts,
    each part at least x, where the order of parts does not matter.
    """
    # Basic validation for non-positive k or n
    if k < 0 or n < 0:
        return 0

    # Subtract the minimal part from each part
    m = n - k * x
    if m < 0:
        return 0

    # Dynamic programming for partitions of m into at most k positive parts
    dp = [[0] * (k + 1) for _ in range(m + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # Only one way to partition zero

    for i in range(1, m + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i][j - 1]
            if i >= j:
                dp[i][j] += dp[i - j][j]

    return dp[m][k]

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    The function handles invalid inputs by raising appropriate exceptions.
    """
    # Basic input validation
    if not isinstance(x0, int) or not isinstance(y0, int):
        raise TypeError("Both x0 and y0 must be integers.")
    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers.")
    # If y0 is not a multiple of x0, no such pairs exist
    if y0 % x0 != 0:
        return 0

    k = y0 // x0  # Product of coprime factors a * b

    def _gcd(a: int, b: int) -> int:
        """Compute the greatest common divisor using Euclid's algorithm."""
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(k ** 0.5)
    for a in range(1, limit + 1):
        if k % a == 0:
            b = k // a
            if _gcd(a, b) == 1:
                count += 1 if a == b else 2
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs (P, Q) of positive integers such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    Arguments:
    x0 -- the required greatest common divisor
    y0 -- the required least common multiple

    Returns:
    The total number of ordered pairs that satisfy the conditions.
    """
    # Validate inputs
    if not isinstance(x0, int) or not isinstance(y0, int):
        return 0
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    n = y0 // x0

    # Helper function for gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1

    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform BFS to transform string A into string B using given replacement rules.
    If transformation within 10 steps, return minimum number of steps; otherwise return 'NO ANSWER!'.
    """
    try:
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"
        # Quick check
        if A == B:
            return 0
        from collections import deque
        queue = deque()
        queue.append((A, 0))
        seen = {A}
        max_steps = 10
        while queue:
            current, steps = queue.popleft()
            if steps >= max_steps:
                continue
            for src, tgt in rules:
                if not isinstance(src, str) or not isinstance(tgt, str):
                    continue
                start = 0
                src_len = len(src)
                while start <= len(current) - src_len:
                    if current.startswith(src, start):
                        new_str = current[:start] + tgt + current[start + src_len:]
                        if new_str == B:
                            return steps + 1
                        if new_str not in seen:
                            seen.add(new_str)
                            queue.append((new_str, steps + 1))
                    start += 1
        return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

def string_transformation(A: str, B: str, rules: list) -> int | str:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses Breadth-First Search (BFS) up to a maximum depth of 10 steps.
    Returns the minimal number of steps required to transform A into B if possible,
    otherwise returns "NO ANSWER!".
    """
    try:
        # Basic validation of inputs
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"
        for rule in rules:
            if (not isinstance(rule, tuple) or len(rule) != 2 or
                not isinstance(rule[0], str) or not isinstance(rule[1], str)):
                return "NO ANSWER!"

        # Immediate success
        if A == B:
            return 0

        visited: set[str] = {A}
        queue: list[tuple[str, int]] = [(A, 0)]

        while queue:
            current, steps = queue.pop(0)

            # Do not explore beyond 10 steps
            if steps >= 10:
                continue

            for src, tgt in rules:
                # Skip rules with empty source to avoid endless loops
                if not src:
                    continue

                start = 0
                while True:
                    idx = current.find(src, start)
                    if idx == -1:
                        break

                    # Construct new string after transformation
                    new_str = current[:idx] + tgt + current[idx + len(src) :]

                    if new_str == B:
                        return steps + 1

                    if new_str not in visited:
                        visited.add(new_str)
                        queue.append((new_str, steps + 1))

                    # Move start past current position to find other overlaps
                    start = idx + 1

        return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

