    valid_rules = []
    for rule in rules:
        if isinstance(rule, tuple) and len(rule) == 2:
            src, tgt = rule
            if isinstance(src, str) and isinstance(tgt, str) and src != "":
                valid_rules.append((src, tgt))
        # Ignore non-tuple or empty source

    if not valid_rules:
        # No transformation possible if no valid rules
        return "NO ANSWER!"

    from collections import deque

    max_steps = 10
    visited = {A}
    queue = deque([(A, 0)])

    while queue:
