def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal
    based on the given statements.

    Parameters
    ----------
    scenario : str
        The name of the participant being tested as the potential criminal.
    liar_count : set
        A set of names of participants who are assumed to be liars.
    statements : dict
        A dictionary mapping participant names to lists of their respective statements.
    days_of_week : set
        A set of strings representing the days of the week.

    Returns
    -------
    bool
        True if the scenario is consistent with the statements, False otherwise.
    """
    # Basic validation of input types
    if not isinstance(scenario, str):
        raise ValueError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise ValueError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise ValueError("statements must be a dictionary")
    if not isinstance(days_of_week, set):
        raise ValueError("days_of_week must be a set")

    # Preprocess days_of_week to lowercase for case-insensitive matching
    days_lower = {day.lower() for day in days_of_week}

    def is_day_statement(statement: str) -> bool:
        """Return True if statement contains a day of the week."""
        stmt_lower = statement.lower()
        for day in days_lower:
            if day in stmt_lower:
                return True
        return False

    def eval_statement_truth(participant: str, statement: str) -> bool | None:
        """Evaluate the truth value of a statement. Return None if cannot parse."""
        stmt = statement.strip()
        # Normalize punctuation: remove trailing periods and commas
        stmt = stmt.rstrip(". ,")
        tokens = [t.strip(" .") for t in stmt.split()]
        if not tokens:
            return None

        # Handle "I am guilty." / "I am not guilty."
        if tokens[0].upper() == "I":
            if len(tokens) >= 3 and tokens[1].lower() == "am":
                if tokens[2].lower() == "guilty":
                    return scenario == participant
                if len(tokens) >= 4 and tokens[2].lower() == "not" and tokens[3].lower() == "guilty":
                    return scenario != participant
            return None

        # Handle "X is guilty." / "X is not guilty."
        subject = tokens[0]
        if len(tokens) >= 3 and tokens[1].lower() == "is":
            if tokens[2].lower() == "guilty":
                return scenario == subject
            if len(tokens) >= 4 and tokens[2].lower() == "not" and tokens[3].lower() == "guilty":
                return scenario != subject
        return None

    # Iterate over each participant and their statements
    for participant, stmts in statements.items():
        # Ensure participant name is a string
        if not isinstance(participant, str):
            raise ValueError("Participant names must be strings")
        is_liar = participant in liar_count
        for stmt in stmts:
            # Skip day-of-week related statements
            if is_day_statement(stmt):
                continue
            truth = eval_statement_truth(participant, stmt)
            if truth is None:
                # If we cannot parse the statement, ignore it
                continue
            if is_liar:
                if truth:
                    # A liar made a true statement – inconsistency
                    return False
            else:
                if not truth:
                    # A truth-teller made a false statement – inconsistency
                    return False
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    try:
        # Basic type checks
        if not isinstance(scenario, str) or not isinstance(liar_count, set) \
                or not isinstance(statements, dict) or not isinstance(days_of_week, set):
            return False

        # Helper to evaluate a single statement
        def evaluate(stmt: str, speaker: str) -> bool | None:
            stmt_lc = stmt.strip().lower()
            # Skip statements about days of the week
            for day in days_of_week:
                if day.lower() in stmt_lc:
                    return None
            # Remove trailing period if present
            if stmt_lc.endswith('.'):
                stmt_lc = stmt_lc[:-1]
            tokens = stmt_lc.split()
            if not tokens:
                return None
            if tokens[0] == 'i':
                if len(tokens) == 3 and tokens[1] == 'am' and tokens[2] == 'guilty':
                    return scenario == speaker
                if len(tokens) == 4 and tokens[1] == 'am' and tokens[2] == 'not' and tokens[3] == 'guilty':
                    return scenario != speaker
                return None
            else:
                # Assume format: NAME is guilty / NAME is not guilty
                if len(tokens) == 3 and tokens[1] == 'is' and tokens[2] == 'guilty':
                    name = tokens[0].upper()
                    return scenario == name
                if len(tokens) == 4 and tokens[1] == 'is' and tokens[2] == 'not' and tokens[3] == 'guilty':
                    name = tokens[0].upper()
                    return scenario != name
                return None

        # Iterate over all statements
        for speaker, stmts in statements.items():
            if not isinstance(stmts, list):
                return False
            for stm in stmts:
                if not isinstance(stm, str):
                    return False
                outcome = evaluate(stm, speaker.upper())
                # Skip unevaluable statements
                if outcome is None:
                    continue
                is_liar = speaker.upper() in liar_count
                # Liars must produce false statements; truth-tellers must produce true statements
                if is_liar and outcome:
                    return False
                if not is_liar and not outcome:
                    return False
        return True
    except Exception:
        # Any unexpected error results in an inconsistent scenario
        return False

