    Any statement that contains a day of the week is ignored.

    Parameters:
        scenario (str): Name of the participant being tested as the potential criminal.
        liar_count (set): Set of names of participants who are assumed to be liars.
        statements (dict): Dictionary mapping participant names to lists of their statements.
        days_of_week (set): Set of strings representing the days of the week.

    Returns:
        bool: True if the scenario is consistent with the statements, False otherwise.
    """
    try:
        # Normalize names for case-insensitive comparison
        scenario_name = scenario.upper()
        days_lower = set(day.upper() for day in days_of_week)

        for speaker, stmts in statements.items():
            speaker_name = speaker.upper()
            for stmt in stmts:
                # Skip if statement mentions any day of the week
                if any(day in stmt.upper() for day in days_lower):
                    continue

                # Remove common trailing punctuation
                cleaned = stmt.strip().rstrip('.,?')
                if not cleaned:
                    continue

                tokens = cleaned.split()
                truth_value = None

                # Handle "I am guilty." / "I am not guilty."
                if len(tokens) >= 3 and tokens[0].lower() in {"i", "me"} and tokens[1].lower() == "am":
                    if tokens[2].lower() == "guilty":
                        truth_value = (scenario_name == speaker_name)
                    elif len(tokens) >= 4 and tokens[2].lower() == "not" and tokens[3].lower() == "guilty":
                        truth_value = (scenario_name != speaker_name)

                # Handle "<NAME> is guilty." / "<NAME> is not guilty."
                elif len(tokens) >= 3 and tokens[1].lower() == "is":
                    target_name = tokens[0].upper()
                    if tokens[2].lower() == "guilty":
                        truth_value = (scenario_name == target_name)
                    elif len(tokens) >= 4 and tokens[2].lower() == "not" and tokens[3].lower() == "guilty":
                        truth_value = (scenario_name != target_name)

                # If the statement didn't match known patterns, ignore it
                if truth_value is None:
                    continue

                is_liar = speaker_name in (name.upper() for name in liar_count)

                if is_liar and truth_value:
                    return False
                if not is_liar and not truth_value:
                    return False

        return True
    except Exception:
        return False

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    if not isinstance(scenario, str) or not isinstance(liar_count, set) or not isinstance(statements, dict) or not isinstance(days_of_week, set):
        return False

    # Precompile regex patterns for statements
    self_pattern = re.compile(r'^I am (not )?guilty$', re.IGNORECASE)
    other_pattern = re.compile(r'^(\w+) is (not )?guilty$', re.IGNORECASE)

    # Helper to check if a statement refers to a day of week
    def ignores_day(stmt: str) -> bool:
        lower = stmt.lower()
        for day in days_of_week:
            if day.lower() in lower:
                return True
        return False

    for speaker, stmts in statements.items():
        # Ensure speaker is a string and stmts is iterable
        if not isinstance(speaker, str) or not isinstance(stmts, list):
            return False
        is_liar = speaker in liar_count
        for stmt in stmts:
            if not isinstance(stmt, str):
                continue  # skip invalid statements
            if ignores_day(stmt):
                continue  # ignore statements about day of week
            stmt_clean = stmt.strip().rstrip('.')
            match = self_pattern.match(stmt_clean)
            if match:
                subject_is_guilty = (scenario == speaker)
                not_flag = bool(match.group(1))
                truth = not subject_is_guilty if not_flag else subject_is_guilty
            else:
                match = other_pattern.match(stmt_clean)
                if match:
                    subject = match.group(1)
                    not_flag = bool(match.group(2))
                    subject_is_guilty = (scenario == subject)
                    truth = not subject_is_guilty if not_flag else subject_is_guilty
                else:
                    # Unknown statement format; skip
                    continue
            # Evaluate consistency with liar status
            if is_liar:
                if truth:
                    return False
            else:
                if not truth:
                    return False
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.
    Parameters:
        scenario (str): The name of the participant being tested as the potential criminal.
        liar_count (set): A set of names of participants who are assumed to be liars.
        statements (dict): A dictionary mapping participant names to lists of their respective statements.
        days_of_week (set): A set of strings representing the days of the week.
    Returns:
        bool: True if the scenario is consistent with the statements, False otherwise.
    """
    import re
    if not isinstance(scenario, str):
        raise ValueError("scenario must be a string")
    if not isinstance(liar_count, set):
        raise ValueError("liar_count must be a set")
    if not isinstance(statements, dict):
        raise ValueError("statements must be a dict")
    if not isinstance(days_of_week, set):
        raise ValueError("days_of_week must be a set")

    scenario = scenario.upper()

    # Precompile regex patterns for guilt statements
    guilty_pattern = re.compile(r'(?i)^(?P<subj>\w+)\s+is\s+(not\s+)?guilty\.?')      # X is guilty. / X is not guilty.
    i_guilty_pattern = re.compile(r'(?i)^I\s+am\s+(not\s+)?guilty\.?')                  # I am guilty. / I am not guilty.

    # Pre-prepare day-of-week words set in uppercase
    days_set = {day.upper() for day in days_of_week}

    def statement_truth(participant: str, stmt: str) -> bool:
        """Evaluate truth value of a guilt-related statement; return False if not a guilt statement."""
        stmt_strip = stmt.strip()
        # Ignore statements containing a day of week
        if any(day in stmt_strip.upper() for day in days_set):
            return None  # not evaluated
        stmt_lower = stmt_strip.lower()

        # Check for self statements
        if i_guilty_pattern.match(stmt_strip):
            m = i_guilty_pattern.match(stmt_strip)
            neg = bool(m.group(1))
            subject_name = participant.upper()
            if neg:
                return subject_name != scenario
            else:
                return subject_name == scenario

        m = guilty_pattern.match(stmt_strip)
        if m:
            sub = m.group('subj')
            neg = bool(m.group(2))
            subject_name = sub.upper()
            if neg:
                return subject_name != scenario
            else:
                return subject_name == scenario

        # If not a guilt-related statement, ignore
        return None

    for participant, stmts in statements.items():
        if not isinstance(participant, str):
            continue
        if not isinstance(stmts, list):
            continue
        for stmt in stmts:
            if not isinstance(stmt, str):
                continue
            truth_val = statement_truth(participant, stmt)
            if truth_val is None:
                continue  # skip non-guilt or day-related

            # Determine if participant is liar or truth-teller
            is_liar = participant.upper() in {name.upper() for name in liar_count}
            if is_liar:
                if truth_val:
                    return False  # liar told truth
            else:
                if not truth_val:
                    return False  # truth-teller told falsehood
    return True

