def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.
    Uses a dynamic programming approach to solve the 0/1 knapsack problem.

    Parameters:
    ----------
    T : int
        The total time available for picking herbs.
    M : int
        The number of different herbs in the cave (not strictly required but used for validation).
    herbs : List[Tuple[int, int]]
        A list of tuples, each containing the time cost and value of a herb.

    Returns:
    -------
    int
        The maximum total value that can be obtained without exceeding the time limit.
    """
    try:
        if not isinstance(T, int) or T < 0:
            raise ValueError("T must be a non‑negative integer")
        if not isinstance(M, int) or M < 0:
            raise ValueError("M must be a non‑negative integer")
        if not isinstance(herbs, list):
            raise ValueError("herbs must be a list of tuples")

        for idx, item in enumerate(herbs):
            if not (isinstance(item, tuple) and len(item) == 2):
                raise ValueError(f"Herb at index {idx} is not a tuple of two integers")
            time, value = item
            if not isinstance(time, int) or time < 0:
                raise ValueError(f"Time cost for herb at index {idx} must be a non‑negative integer")
            if not isinstance(value, int) or value < 0:
                raise ValueError(f"Value for herb at index {idx} must be a non‑negative integer")

        # Dynamic programming array where dp[t] is the max value achievable with time t
        dp = [0] * (T + 1)

        for time, value in herbs:
            if time > T:
                continue  # Cannot pick this herb within the time limit
            for current in range(T, time - 1, -1):
                new_val = dp[current - time] + value
                if new_val > dp[current]:
                    dp[current] = new_val

        return dp[T]

    except Exception:
        # In case of any unexpected issue, safely return 0
        return 0

