def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    """
    Calculates the minimal remaining space in a box of capacity V after packing a subset of items
    with volumes provided in the list 'volumes'. The function returns the difference between
    the box capacity and the maximum volume that can be occupied by any subset of the items.
    """
    # Basic input validation
    if not isinstance(V, int) or V < 0:
        raise ValueError("Box capacity V must be a non‑negative integer")
    if not isinstance(n, int) or n < 0:
        raise ValueError("Number of items n must be a non‑negative integer")
    if not isinstance(volumes, list):
        raise TypeError("volumes must be a list of integers")

    # When no items are available or n is zero, the remaining space equals the full capacity
    if n <= 0 or not volumes:
        return V

    # Ensure consistency between declared n and actual list length
    if len(volumes) != n:
        # Adjust n to actual length if possible; otherwise, use the list length
        n = len(volumes)

    # Dynamic programming table: dp[i] will be True if volume i can be achieved
    dp = [False] * (V + 1)
    dp[0] = True  # Zero volume is always achievable with no items

    for vol in volumes:
        # Skip non‑integer or negative values
        try:
            vol_int = int(vol)
        except Exception:
            continue
        if vol_int <= 0 or vol_int > V:
            # Ignore zero or negative items and those that exceed the box capacity
            continue

        # Update dp table from high to low to avoid reuse of the same item
        for current in range(V, vol_int - 1, -1):
            if dp[current - vol_int]:
                dp[current] = True

    # Find the largest achievable volume not exceeding V
    max_occupied = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied = i
            break

    return V - max_occupied

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    Uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items and returns the difference between the
    box's total capacity and this maximum occupied volume.

    Args:
        V: The total capacity of the box (non‑negative integer).
        n: The number of items to consider for packing into the box (non‑negative integer).
        volumes: A list of the volumes of the n items (non‑negative integers).

    Returns:
        int: The minimum remaining space in the box after packing.

    Raises:
        ValueError: If inputs are invalid (negative values, type mismatches, length mismatch).
    """
    # Validate inputs
    try:
        if not isinstance(V, int) or V < 0:
            raise ValueError("V must be a non‑negative integer")
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non‑negative integer")
        if not isinstance(volumes, list):
            raise ValueError("volumes must be a list")
        if len(volumes) != n:
            raise ValueError("Length of volumes must equal n")
        for v in volumes:
            if not isinstance(v, int) or v < 0:
                raise ValueError("All volumes must be non‑negative integers")
    except Exception as exc:
        raise ValueError(f"Invalid input: {exc}") from exc

    # If there is no capacity or no items, remaining space is the full capacity
    if V == 0 or n == 0 or all(v == 0 for v in volumes):
        return V

    # Dynamic programming: dp[i] indicates whether a total volume i can be achieved
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            # Items that exceed the box capacity cannot be used
            continue
        # Update dp table in reverse to avoid reusing the same item
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True

    # Find the largest volume that can be achieved
    best = 0
    for cap in range(V, -1, -1):
        if dp[cap]:
            best = cap
            break

    return V - best

