    """
    Calculate the minimum number of students that need to leave to form a choir formation.

    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    try:
        if not isinstance(heights, list):
            raise ValueError("heights must be a list")
        n = len(heights)
        if n == 0:
            return 0
        # Compute lengths of strictly increasing subsequence ending at each index
        lis = [1] * n
        for i in range(n):
            for j in range(i):
                if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                    lis[i] = lis[j] + 1
        # Compute lengths of strictly decreasing subsequence starting at each index
        lds = [1] * n
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                    lds[i] = lds[j] + 1
        # Find maximum length of bitonic subsequence
        max_len = 0
        for i in range(n):
            curr = lis[i] + lds[i] - 1
            if curr > max_len:
                max_len = curr
        return n - max_len
    except Exception as e:
        # In case of unexpected input or runtime error, return 0 as safe fallback
        return 0

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave so that the remaining
    heights form a bitonic sequence (strictly increasing to a peak and then strictly
    decreasing).

    Parameters
    ----------
    heights : list of int
        A list of student heights.

    Returns
    -------
    int
        The minimum number of students that need to leave.

    Raises
    ------
    ValueError
        If the input is not a list of integers.
    """
    try:
        if not isinstance(heights, list):
            raise ValueError("Input must be a list.")
        n = len(heights)
        if n <= 1:
            return 0
        # Validate that all elements are integers
        for h in heights:
            if not isinstance(h, int):
                raise ValueError("All heights must be integers.")
    except Exception as e:
        raise ValueError(f"Invalid input: {e}")

    # Compute Longest Increasing Subsequence (LIS) lengths ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute Longest Decreasing Subsequence (LDS) lengths starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum removals to achieve a bitonic formation
    return n - max_bitonic

def hanoi_double_iterative(n: int) -> int:
    """
    Calculate the minimum number of moves required to solve the double-disc
    Hanoi Towers problem for n pairs of discs using an iterative algorithm.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    moves = 0
    for _ in range(n):
        moves = 2 * moves + 2
    return moves
